import{_ as o,o as l,c as i,aw as r}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Запахи кода (Code Smell)","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/refactoring/best-practices/code-smell.md","filePath":"wiki/dev-commit/theory/refactoring/best-practices/code-smell.md"}'),s={name:"wiki/dev-commit/theory/refactoring/best-practices/code-smell.md"};function e(n,t,a,g,c,d){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="запахи-кода-code-smell" tabindex="-1">Запахи кода (Code Smell) <a class="header-anchor" href="#запахи-кода-code-smell" aria-label="Permalink to &quot;Запахи кода (Code Smell)&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Определение</p><ul><li><strong>Code Smell (Запахи кода)</strong> - код с признаками (запахами) проблем в системе</li><li>Запахи кода - ключевые признаки необходимости рефакторинга</li><li>Запахи кода - это не набор чётких правил, а описание мест, на которые нужно обращать внимание при рефакторинге</li></ul></div><h2 id="общие-запахи-объектно-ориентированного-кода" tabindex="-1">Общие запахи объектно-ориентированного кода <a class="header-anchor" href="#общие-запахи-объектно-ориентированного-кода" aria-label="Permalink to &quot;Общие запахи объектно-ориентированного кода&quot;">​</a></h2><ol><li><strong>Дублирование кода</strong> - использование одинаковых структур кода в нескольких местах</li><li><strong>Длинный метод</strong></li><li><strong>Большой класс</strong></li><li><strong>Длинный список параметров</strong> - использование объектов позволяет, в случае изменения передаваемых данных, модифицировать только сам объект</li><li><strong>Расходящиеся модификации</strong> - проблема возникает, когда при модификации в системе невозможно выделить определённое место, которое нужно изменить</li><li><strong>Стрельба дробью</strong> - при выполнении любых модификаций приходится вносить множество мелких изменений в большое число классов</li><li><strong>Завистливые функции</strong> - метод обращается к данным другого объекта чаще, чем к собственным данным</li><li><strong>Группы данных</strong> - группы данных, встречающихся совместно, нужно превращать в самостоятельный класс</li><li><strong>Одержимость элементарными типами</strong> - проблема связана с использованием элементарных типов вместо маленьких объектов для небольших задач, таких как валюта, диапазоны, специальные строки для телефонных номеров и т.д.</li><li><strong>Операторы типа switch</strong> - часто один и тот же блок switch оказывается разбросанным по разным местам программы. При добавлении в переключатель нового варианта приходится искать все эти блоки switch и модифицировать их</li><li><strong>Параллельные иерархии наследования</strong> - всякий раз при порождении подкласса одного из классов приходится создавать подкласс другого класса</li><li><strong>Ленивый класс</strong> - класс, затраты на существование которого не окупаются выполняемыми им функциями, должен быть ликвидирован</li><li><strong>Теоретическая общность</strong> - на определённом этапе существования программы обеспечивается набор механизмов, который, возможно, потребуется для некоторой будущей функциональности. Программу становится труднее понимать и сопровождать</li><li><strong>Временное поле</strong> - поле, которое нужно объекту только при определённых обстоятельствах. Такое положение вещей трудно для понимания, так как ожидается, что объекту нужны все его поля</li><li><strong>Цепочка вызовов</strong> - появляется тогда, когда клиент запрашивает у одного объекта другой объект, другой объект запрашивает ещё один объект и т. д. Такие последовательности вызовов означают, что клиент связан с навигацией по структуре классов. Любые изменения промежуточных связей означают необходимость модификации клиента</li><li><strong>Посредник</strong> - чрезмерное использование делегирования может привести к появлению классов, у которых большинство методов состоит только из вызова метода другого класса</li><li><strong>Неуместная близость</strong> - возникает тогда, когда классы чаще, чем следовало бы, погружены в закрытые части друг друга</li><li><strong>Альтернативные классы с разными интерфейсами</strong> - два класса, в которых часть функциональности общая, но методы, реализующие её, имеют разные параметры</li><li><strong>Неполнота библиотечного класса</strong> - библиотеки через некоторое время перестают удовлетворять требованиям пользователей. Естественное решение — поменять кое-что в библиотеках, но библиотечные классы не изменять</li><li><strong>Классы данных</strong> - это классы, которые содержат только поля и методы для доступа к ним, это просто контейнеры для данных, используемые другими классами</li><li><strong>Отказ от наследства</strong> - если наследник использует лишь малую часть унаследованных методов и свойств родителя, это является признаком неправильной иерархии</li><li><strong>Комментарии</strong> - почувствовав потребность написать комментарий, попробуйте изменить структуру кода так, чтобы любые комментарии стали излишними</li></ol>',5)])])}const _=o(s,[["render",e]]);export{h as __pageData,_ as default};
